1699	/// The tool results of the transfer calls of one handoff, in call order.
1700	///
1701	/// `started` tells whether the target agent's `run` returned `Ok`. When it
1702	/// did, the first call gets `transferred to {target}`, and each other call
1703	/// of the same response gets a "transfer not performed" text. When it did
1704	/// not, every call gets `transfer failed: {target} did not start`. The text
1705	/// holds no error detail, because the result goes to a model.
1706	fn transfer_results(call_ids: &[String], target: &str, started: bool) -> Vec<crate::Item> {
1707	    call_ids
1708	        .iter()
1709	        .enumerate()
1710	        .map(|(i, call_id)| {
1711	            let text = if !started {
1712	                format!("transfer failed: {target} did not start")
1713	            } else if i == 0 {
1714	                format!("transferred to {target}")
1715	            } else {
1716	                format!("transfer not performed: this response already transferred to {target}")
1717	            };
1718	            crate::Item::ToolResult {
1719	                call_id: call_id.clone(),
1720	                content: vec![crate::ContentPart::Text { text }],
1721	            }
1722	        })
1723	        .collect()
1724	}
