1830	/// Out-of-band carrier for a run's terminal structured [`AgentError`].
1831	///
1832	/// The [`crate::AgentEvent`] stream stays string-based
1833	/// ([`crate::AgentEvent::RunFailed`]` { error: String }`) so it remains `Clone`
1834	/// and snapshot-stable; the structured error rides this side-channel instead.
1835	/// One slot lives on each [`RunContext`]; the agent records into it at the
1836	/// moment of failure and a [`crate::Runner`] (or
1837	/// [`crate::RunResultStreaming::collect`]) reads it **after the event stream is
1838	/// fully drained** — see [`crate::RunResultStreaming::collect`] for why the
1839	/// read must come after draining.
1840	#[derive(Clone, Default, Debug)]
1841	pub struct FailureSlot(Arc<Mutex<Option<AgentError>>>);
1842	
1843	impl FailureSlot {
1844	    /// Create an empty slot.
1845	    pub fn new() -> Self {
1846	        Self::default()
1847	    }
1848	
1849	    /// Record the terminal structured error. Called once per run, at any point
1850	    /// before the stream terminates; last write wins.
1851	    pub fn set(&self, err: AgentError) {
1852	        *self.0.lock().unwrap_or_else(|e| e.into_inner()) = Some(err);
1853	    }
1854	
1855	    /// Take the recorded error, if any. Read once at the boundary, after the
1856	    /// event stream has been fully drained.
1857	    pub fn take(&self) -> Option<AgentError> {
1858	        self.0.lock().unwrap_or_else(|e| e.into_inner()).take()
1859	    }
1860	}
