1862	// A non-`Send`/`Sync` payload added to `AgentError` would silently break the
1863	// agent's `BoxStream<'static, AgentEvent>: Send` bound far downstream. Fail here
1864	// instead, with a clear pointer to the cause.
1865	const _: fn() = || {
1866	    fn assert_send_sync<T: Send + Sync>() {}
1867	    assert_send_sync::<FailureSlot>();
1868	};
