1	//! Pure step machine for the Temporal-backed durable agent loop.
2	//!
3	//! [`crate::driver::DurableDriver`] mirrors `paigasus-helikon-core`'s
4	//! ephemeral driver — the inline step loop inside `LlmAgent::run`
5	//! (`crates/paigasus-helikon-core/src/agent.rs`) — but instead
6	//! of directly calling a [`Model`] or [`Tool`](paigasus_helikon_core::Tool)
7	//! it yields a [`crate::driver::DriverEffect`] the caller must satisfy
8	//! out-of-band (a Temporal activity) and feed back via `apply_*`. This keeps
9	//! the loop **SDK-free**: no `temporalio-*` import appears in this module,
10	//! so it can be unit-tested without a Temporal worker and reused verbatim by
11	//! the Task 8 workflow, which is a mechanical executor of the effects this
12	//! module produces.
13	//!
14	//! [`Model`]: paigasus_helikon_core::Model
15	//!
16	//! # Ordering contract
17	//!
18	//! [`paigasus_helikon_core::transition`] reads the driver's conversation but
19	//! never appends to it — the driver owns all conversation mutation. Per
20	//! `loop_state.rs`'s `ToolResults` arm (and the ephemeral driver's mirror —
21	//! its `Item::ToolResult`-append site in the `NextAction::ExecuteTools` arm
22	//! of `LlmAgent::run`), the split is:
23	//! - The driver appends [`paigasus_helikon_core::Item::ToolResult`]/model-turn
24	//!   items to its conversation directly, in
25	//!   [`crate::driver::DurableDriver::apply_model`] and
26	//!   [`crate::driver::DurableDriver::apply_tools`].
27	//! - `transition` only *emits events* describing those items
28	//!   (`AgentEvent::ToolOutputItem`, `AgentEvent::MessageOutput`, ...); it
29	//!   never mutates the conversation itself.
30	//!
31	//! Violating this (e.g. having `transition` also push `Item::ToolResult`)
32	//! would double-append tool results into the conversation the next
33	//! `CallModel` request carries.
34	
35	use paigasus_helikon_core::{
36	    transition, AgentEvent, ContentPart, Item, LoopState, ModelRequest, ModelSettings, NextAction,
37	    OutputType, RunInterrupt, TokenUsage, ToolCallOutcome, ToolCallRequest, ToolDef, TransitionCtx,
38	    TransitionInput, TransitionOutcome,
39	};
40	
41	use crate::error::ErrorKindPayload;
42	use crate::payloads::{
43	    DriverConfig, DurableRunOutcome, FinalOutputPayload, ModelTurnResult, RunStatusPayload,
44	    WorkflowInput,
45	};
46	
47	/// What the workflow must do next.
48	///
49	/// Task 8's workflow is a mechanical executor of this enum: each variant
50	/// names exactly one Temporal activity (or termination) to invoke, and the
51	/// activity's result feeds back through the matching `apply_*` method.
52	#[derive(Debug)]
53	pub enum DriverEffect {
54	    /// Run the render_instructions activity (always the first effect).
55	    RenderInstructions,
56	    /// Invoke the model with this request; feed the result to
57	    /// [`DurableDriver::apply_model`] (or [`DurableDriver::apply_model_failure`]
58	    /// on a non-retryable error).
59	    CallModel(ModelRequest),
60	    /// Execute these tool calls (concurrently, subject to
61	    /// [`DriverConfig::parallel_tool_call_limit`]); feed the outcomes back
62	    /// via [`DurableDriver::apply_tools`] **in this same order**.
63	    ExecuteTools(Vec<ToolCallRequest>),
64	    /// The run has reached a terminal outcome; stop driving.
65	    Finished(DurableRunOutcome),
66	}
67	
68	/// Static agent definition the driver plans against (worker-registered).
69	///
70	/// Built once per agent by whoever registers the Temporal worker (mirroring
71	/// the tool/model/output-type configuration an [`paigasus_helikon_core::LlmAgent`]
72	/// carries) and handed to [`DurableDriver::new`] alongside the per-run
73	/// [`WorkflowInput`].
74	#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
75	pub struct AgentPlan {
76	    /// Tool definitions available this run.
77	    pub tool_defs: Vec<ToolDef>,
78	    /// Provider-tuning knobs.
79	    pub model_settings: ModelSettings,
80	    /// Structured-output type, when the agent configured one.
81	    pub output: Option<OutputType>,
82	}
83	
84	/// Former name of [`paigasus_helikon_core::RunInterrupt`].
85	///
86	/// `driver` is a `pub mod`, so this name is public API; it is kept as an alias
87	/// so downstream `crate::driver::InterruptKind` paths (and
88	/// `InterruptKind::Cancelled` variant access, which resolves through a type
89	/// alias) keep working. The rule this type participates in now lives in core
90	/// (SMA-422).
91	///
92	/// Note the alias is not a perfect source-compatibility shim: because
93	/// `RunInterrupt` is `#[non_exhaustive]` and foreign, a downstream exhaustive
94	/// `match` on it now requires a wildcard arm.
95	#[deprecated(note = "renamed; use `paigasus_helikon_core::RunInterrupt` instead")]
96	pub type InterruptKind = paigasus_helikon_core::RunInterrupt;
97	
98	/// Internal driving phase. Not part of the public API.
99	#[derive(Debug)]
100	enum Phase {
101	    /// Waiting on the render_instructions activity result.
102	    AwaitingInstructions,
103	    /// Normal operation: `next_effect` runs `transition` against
104	    /// `pending_input`.
105	    Driving,
106	    /// Terminal: the outcome is cached so repeated `next_effect` calls (and
107	    /// `interrupt`) are idempotent instead of re-driving a finished loop.
108	    Done(DurableRunOutcome),
109	}
110	
111	/// Pure step machine for one durable agent run.
112	///
113	/// Owns the conversation, the [`LoopState`], the accumulated event log, and
114	/// the running usage total; advances by alternating [`Self::next_effect`]
115	/// (what to do next) with the matching `apply_*` call (the activity's
116	/// result). Contains **no** Temporal SDK types or async code — a Temporal
117	/// workflow drives it, but this type has no idea Temporal exists.
118	pub struct DurableDriver {
119	    agent_name: String,
120	    plan: AgentPlan,
121	    config: DriverConfig,
122	    /// The run's seed messages (`WorkflowInput::conversation`), held until
123	    /// [`Self::apply_instructions`] seeds the real conversation with the
124	    /// system item ahead of them.
125	    seed_messages: Vec<Item>,
126	    conversation: Vec<Item>,
127	    loop_state: LoopState,
128	    pending_input: Option<TransitionInput>,
129	    events: Vec<AgentEvent>,
130	    /// Cumulative usage as of the most recent [`LoopState`] that carried one
131	    /// (every variant except `Failed`/`Compacting`/`NeedsApproval`). Read at
132	    /// interrupt/failure time instead of recomputed, since `LoopState::Failed`
133	    /// itself carries no usage.
134	    usage: TokenUsage,
135	    phase: Phase,
136	}
137	
138	impl DurableDriver {
139	    /// Start a new driver for one run. Does not seed the conversation yet —
140	    /// call [`Self::next_effect`] (yields [`DriverEffect::RenderInstructions`])
141	    /// then [`Self::apply_instructions`] to do that.
142	    pub fn new(input: WorkflowInput, plan: AgentPlan) -> Self {
143	        Self {
144	            agent_name: input.agent_name,
145	            plan,
146	            config: input.config,
147	            seed_messages: input.conversation,
148	            conversation: Vec::new(),
149	            loop_state: LoopState::CallingModel {
150	                turn: 0,
151	                usage: TokenUsage::default(),
152	            },
153	            pending_input: None,
154	            events: Vec::new(),
155	            usage: TokenUsage::default(),
156	            phase: Phase::AwaitingInstructions,
157	        }
158	    }
159	
160	    /// What the workflow must do next.
161	    ///
162	    /// Idempotent at the boundaries: called before [`Self::apply_instructions`]
163	    /// it always returns [`DriverEffect::RenderInstructions`]; called again
164	    /// after a terminal outcome it replays the same [`DriverEffect::Finished`]
165	    /// rather than re-driving a finished loop.
166	    ///
167	    /// # Panics
168	    ///
169	    /// Panics if called with no pending transition input queued — i.e.
170	    /// calling `next_effect` twice in a row without an intervening
171	    /// `apply_instructions`/`apply_model`/`apply_model_failure`/`apply_tools`
172	    /// call in between (outside the `RenderInstructions`/`Finished` idempotent
173	    /// boundaries above, where no pending input is ever expected). The
174	    /// workflow's own effect loop always alternates `next_effect`/`apply_*`
175	    /// correctly by construction, so this should not fire in practice.
176	    pub fn next_effect(&mut self) -> DriverEffect {
177	        match &self.phase {
178	            Phase::AwaitingInstructions => return DriverEffect::RenderInstructions,
179	            Phase::Done(outcome) => return DriverEffect::Finished(outcome.clone()),
180	            Phase::Driving => {}
181	        }
182	
183	        let tx_ctx = TransitionCtx {
184	            tools: &self.plan.tool_defs,
185	            model_settings: &self.plan.model_settings,
186	            max_turns: self.config.max_turns,
187	            conversation: &self.conversation,
188	            output: self.plan.output.as_ref(),
189	            handoffs: &[],
190	        };
191	        let tx_input = self
192	            .pending_input
193	            .take()
194	            .expect("next_effect called without a pending transition input (apply_* not called)");
195	        let TransitionOutcome {
196	            next_state,
197	            events,
198	            next_action,
199	            conversation_appends,
200	        } = transition(&self.loop_state, tx_input, &tx_ctx);
201	
202	        self.events.extend(events);
203	        self.conversation.extend(conversation_appends);
204	        if let Some(u) = state_usage(&next_state) {
205	            self.usage = u;
206	        }
207	
208	        match next_action {
209	            NextAction::CallModel { request } => {
210	                self.loop_state = next_state;
211	                DriverEffect::CallModel(request)
212	            }
213	            NextAction::ExecuteTools { calls } => {
214	                self.loop_state = next_state;
215	                DriverEffect::ExecuteTools(calls)
216	            }
217	            NextAction::Terminate => {
218	                let status = match next_state {
219	                    LoopState::Done(final_output) => {
220	                        RunStatusPayload::Completed(FinalOutputPayload {
221	                            content: final_output.content,
222	                            usage: final_output.usage,
223	                        })
224	                    }
225	                    LoopState::Failed(err) => {
226	                        RunStatusPayload::AgentFailed(ErrorKindPayload::from_agent_error(&err))
227	                    }
228	                    // `transition` never pairs `Terminate` with any other
229	                    // state today, but `LoopState` is `#[non_exhaustive]`.
230	                    other => RunStatusPayload::AgentFailed(ErrorKindPayload::Other {
231	                        message: format!("unexpected terminal state: {other:?}"),
232	                    }),
233	                };
234	                self.finish(status)
235	            }
236	            NextAction::Handoff => {
237	                // Defensively unreachable: `handoffs` above is always `&[]`,
238	                // so `transition` can never select a handoff target. Kept in
239	                // case a later ticket wires handoff-configured agents through
240	                // this driver without updating this match.
241	                let target = match &next_state {
242	                    LoopState::ApplyingHandoff { target, .. } => target.clone(),
243	                    _ => "<unknown>".to_owned(),
244	                };
245	                self.finish(RunStatusPayload::AgentFailed(
246	                    ErrorKindPayload::HandoffUnsupported { target },
247	                ))
248	            }
249	            // `NextAction` is `#[non_exhaustive]`.
250	            other => self.finish(RunStatusPayload::AgentFailed(ErrorKindPayload::Other {
251	                message: format!("unsupported next_action: {other:?}"),
252	            })),
253	        }
254	    }
255	
256	    /// Result of `RenderInstructions`: seed `[System] ++ conversation`, emit
257	    /// `RunStarted`.
258	    pub fn apply_instructions(&mut self, system_text: String) {
259	        let seed_messages = std::mem::take(&mut self.seed_messages);
260	        let mut conversation = Vec::with_capacity(seed_messages.len() + 1);
261	        if !system_text.is_empty() {
262	            conversation.push(Item::System {
263	                content: vec![ContentPart::Text { text: system_text }],
264	            });
265	        }
266	        conversation.extend(seed_messages.iter().cloned());
267	        self.conversation = conversation;
268	
269	        self.events.push(AgentEvent::RunStarted {
270	            agent: self.agent_name.clone(),
271	        });
272	
273	        self.pending_input = Some(TransitionInput::Start {
274	            messages: seed_messages,
275	        });
276	        self.loop_state = LoopState::CallingModel {
277	            turn: 0,
278	            usage: TokenUsage::default(),
279	        };
280	        self.phase = Phase::Driving;
281	    }
282	
283	    /// Feed back a completed model turn.
284	    ///
285	    /// Mirrors the ephemeral driver (`agent.rs`'s `NextAction::CallModel`
286	    /// arm): the driver — not `transition` — appends the turn's items to the
287	    /// conversation, immediately, so the next `next_effect` call's
288	    /// `TransitionCtx::conversation` already includes them.
289	    pub fn apply_model(&mut self, turn: ModelTurnResult) {
290	        let paigasus_helikon_core::ModelTurn {
291	            items,
292	            usage,
293	            finish_reason,
294	            ..
295	        } = turn.0;
296	        self.conversation.extend(items.iter().cloned());
297	        self.pending_input = Some(TransitionInput::ModelResponse {
298	            items,
299	            usage,
300	            finish_reason,
301	        });
302	    }
303	
304	    /// Model activity failed terminally (non-retryable `ErrorKindPayload`
305	    /// json).
306	    ///
307	    /// Bypasses `transition` entirely — like the ephemeral driver's direct
308	    /// `Err(e) => { failure.set(...); yield RunFailed; return; }` paths, a
309	    /// model invocation failure is a terminal event the state machine never
310	    /// sees.
311	    pub fn apply_model_failure(&mut self, kind: ErrorKindPayload) {
312	        let message = kind.clone().into_agent_error().to_string();
313	        self.events.push(AgentEvent::RunFailed { error: message });
314	        self.finish(RunStatusPayload::AgentFailed(kind));
315	    }
316	
317	    /// Feed back completed tool outcomes. Outcomes MUST be passed in
318	    /// original call order (workflow joins in order).
319	    ///
320	    /// Mirrors the ephemeral driver (`agent.rs`'s `NextAction::ExecuteTools`
321	    /// arm): the driver appends one [`Item::ToolResult`] per outcome, in the
322	    /// given order, **before** the next `next_effect` call — `transition`'s
323	    /// `ToolResults` arm only emits `AgentEvent::ToolOutputItem`s describing
324	    /// them, it does not append conversation items itself.
325	    pub fn apply_tools(&mut self, outcomes: Vec<ToolCallOutcome>) {
326	        for o in &outcomes {
327	            self.conversation.push(Item::ToolResult {
328	                call_id: o.call_id.clone(),
329	                content: o
330	                    .result
331	                    .clone()
332	                    .unwrap_or_else(|e| vec![ContentPart::Text { text: e }]),
333	            });
334	        }
335	        self.pending_input = Some(TransitionInput::ToolResults { outcomes });
336	    }
337	
338	    /// Cancel/timeout interruption — partial outcome with events so far.
339	    ///
340	    /// If the run had already reached a terminal state (e.g. a prior
341	    /// `next_effect` call returned `Finished`), that outcome is returned
342	    /// unchanged instead of being overwritten with `Cancelled`/`TimedOut` —
343	    /// a completed run's status is not retroactively an interruption.
344	    pub fn interrupt(self, kind: RunInterrupt) -> DurableRunOutcome {
345	        if let Phase::Done(outcome) = self.phase {
346	            return outcome;
347	        }
348	        let status = match kind {
349	            RunInterrupt::Cancelled => RunStatusPayload::Cancelled,
350	            RunInterrupt::TimedOut => RunStatusPayload::TimedOut,
351	            // `RunInterrupt` is `#[non_exhaustive]`, so a wildcard is required
352	            // here. An interrupt kind this crate does not know is still a run
353	            // that did not finish, so surface it as a failure rather than
354	            // mislabeling it as one of the two known interrupts. Panicking is
355	            // not an option: this runs inside a Temporal workflow, where a
356	            // workflow-task failure retries indefinitely.
357	            other => RunStatusPayload::AgentFailed(ErrorKindPayload::Other {
358	                message: format!("unhandled run interrupt: {other:?}"),
359	            }),
360	        };
361	        DurableRunOutcome {
362	            status,
363	            events: self.events,
364	            usage: self.usage,
365	        }
366	    }
367	
368	    /// Cache `status` (with all accumulated events/usage) as the terminal
369	    /// outcome and return the matching [`DriverEffect::Finished`].
370	    fn finish(&mut self, status: RunStatusPayload) -> DriverEffect {
371	        let outcome = DurableRunOutcome {
372	            status,
373	            events: self.events.clone(),
374	            usage: self.usage,
375	        };
376	        self.phase = Phase::Done(outcome.clone());
377	        DriverEffect::Finished(outcome)
378	    }
379	}
380	
381	/// Extract the cumulative usage carried by states that have one.
382	/// `LoopState` is `#[non_exhaustive]`, so this needs a wildcard arm even
383	/// though every current variant is named.
384	fn state_usage(state: &LoopState) -> Option<TokenUsage> {
385	    match state {
386	        LoopState::CallingModel { usage, .. }
387	        | LoopState::ExecutingTools { usage, .. }
388	        | LoopState::ApplyingHandoff { usage, .. }
389	        | LoopState::Finalizing { usage, .. }
390	        | LoopState::RepairingOutput { usage, .. } => Some(*usage),
391	        LoopState::Done(final_output) => Some(final_output.usage),
392	        _ => None,
393	    }
394	}
395	
