//! Error types for the Temporal-backed durable runtime.

use serde::{Deserialize, Serialize};

use crate::payloads::{DurableRunOutcome, RunStatusPayload};

/// Map a total [`DurableRunOutcome`] onto the [`crate::error`]-external
/// [`paigasus_helikon_core::Runner`] boundary types.
///
/// This is the durable-runner mirror of `TokioRunner`'s terminal-outcome
/// handling: the workflow always returns a `DurableRunOutcome` (finalize on
/// every exit path), and this function projects its four terminal states onto
/// the runner's `Result<RunResult, RunError>`:
///
/// - [`RunStatusPayload::Completed`] → `Ok(RunResult)` whose `final_output` is
///   the concatenated [`paigasus_helikon_core::ContentPart::Text`] parts of the
///   final output (the `FinalOutput::as_text` convention), carrying the run's
///   events and cumulative usage.
/// - [`RunStatusPayload::AgentFailed`] → `Err(RunError::Agent(..))`, the typed
///   [`paigasus_helikon_core::AgentError`] reconstructed from the wire payload.
/// - [`RunStatusPayload::Cancelled`] → `Err(RunError::Cancelled)`.
/// - [`RunStatusPayload::TimedOut`] → `Err(RunError::Timeout)`.
pub(crate) fn outcome_to_run_result(
    outcome: DurableRunOutcome,
) -> Result<paigasus_helikon_core::RunResult, paigasus_helikon_core::RunError> {
    use paigasus_helikon_core::ContentPart;

    let DurableRunOutcome {
        status,
        events,
        usage,
    } = outcome;

    match status {
        RunStatusPayload::Completed(final_output) => {
            let final_text = final_output
                .content
                .iter()
                .filter_map(|part| match part {
                    ContentPart::Text { text } => Some(text.as_str()),
                    _ => None,
                })
                .collect::<Vec<_>>()
                .join("");
            // `RunResult` is `#[non_exhaustive]`, so it cannot be built with a
            // struct literal from outside `paigasus-helikon-core`; construct
            // via `Default` (which yields `RunResult<String>`) then assign.
            let mut result = paigasus_helikon_core::RunResult::default();
            result.final_output = final_text;
            result.events = events;
            result.usage = usage;
            Ok(result)
        }
        RunStatusPayload::AgentFailed(kind) => Err(paigasus_helikon_core::RunError::Agent(
            kind.into_agent_error(),
        )),
        RunStatusPayload::Cancelled => {
            Err(paigasus_helikon_core::RunInterrupt::Cancelled.run_error())
        }
        RunStatusPayload::TimedOut => {
            Err(paigasus_helikon_core::RunInterrupt::TimedOut.run_error())
        }
    }
}

/// Serializable error payload for crossing Temporal boundaries.
///
/// `AgentError` contains non-serializable variants (particularly `Other` with
/// `anyhow::Error`), so this type provides a wire-safe projection that can
/// be serialized and deserialized through Temporal activities.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum ErrorKindPayload {
    /// Agent exhausted its turn budget before reaching a final output.
    MaxTurnsExceeded(u32),
    /// Structured output validation failed even after one repair attempt.
    InvalidStructuredOutput {
        /// Human-readable schema/validation errors.
        schema_errors: Vec<String>,
        /// The raw terminal assistant text that failed validation.
        final_text: String,
    },
    /// A downstream model call failed.
    Model {
        /// Error message from the model.
        message: String,
    },
    /// Handoff target is not supported (not yet used in Temporal workflow).
    HandoffUnsupported {
        /// The handoff target that was not supported.
        target: String,
    },
    /// Catch-all for all other agent errors.
    Other {
        /// Error message.
        message: String,
    },
}

impl ErrorKindPayload {
    /// Lossy projection from [`paigasus_helikon_core::AgentError`].
    ///
    /// Converts the typed error surface into a serializable form for
    /// transmission through Temporal. Some variants (especially `Other` with
    /// `anyhow::Error`) degrade to string messages, as `anyhow::Error` is
    /// not `Serialize`.
    ///
    /// # Mapping
    ///
    /// - `MaxTurnsExceeded(n)` → `Self::MaxTurnsExceeded(n)`
    /// - `InvalidStructuredOutput { schema_errors, final_text }` → `Self::InvalidStructuredOutput { .. }`
    /// - `Model(e)` → `Self::Model { message: e.to_string() }`
    /// - Everything else (Tool, Session, Guardrail, HookDenied, etc.) → `Self::Other { message }`
    pub fn from_agent_error(e: &paigasus_helikon_core::AgentError) -> Self {
        match e {
            paigasus_helikon_core::AgentError::MaxTurnsExceeded(n) => Self::MaxTurnsExceeded(*n),
            paigasus_helikon_core::AgentError::InvalidStructuredOutput {
                schema_errors,
                final_text,
            } => Self::InvalidStructuredOutput {
                schema_errors: schema_errors.clone(),
                final_text: final_text.clone(),
            },
            paigasus_helikon_core::AgentError::Model(e) => Self::Model {
                message: e.to_string(),
            },
            _ => Self::Other {
                message: e.to_string(),
            },
        }
    }

    /// Reconstruction into the typed error surface the Runner returns.
    ///
    /// Converts this serializable form back into an [`paigasus_helikon_core::AgentError`]
    /// for downstream error handling. Lossy variants (like `Other`) reconstruct
    /// with the stored message.
    pub fn into_agent_error(self) -> paigasus_helikon_core::AgentError {
        match self {
            Self::MaxTurnsExceeded(n) => paigasus_helikon_core::AgentError::MaxTurnsExceeded(n),
            Self::InvalidStructuredOutput {
                schema_errors,
                final_text,
            } => paigasus_helikon_core::AgentError::InvalidStructuredOutput {
                schema_errors,
                final_text,
            },
            Self::Model { message } => {
                paigasus_helikon_core::AgentError::Other(anyhow::anyhow!(message))
            }
            Self::HandoffUnsupported { target } => paigasus_helikon_core::AgentError::Other(
                anyhow::anyhow!("handoff unsupported: {}", target),
            ),
            Self::Other { message } => {
                paigasus_helikon_core::AgentError::Other(anyhow::anyhow!(message))
            }
        }
    }
}

#[cfg(test)]
mod outcome_mapping_tests {
    use super::*;
    use crate::payloads::{DurableRunOutcome, FinalOutputPayload};
    use paigasus_helikon_core::{AgentError, ContentPart, RunError, TokenUsage};

    fn usage(input_tokens: u64, output_tokens: u64) -> TokenUsage {
        // `TokenUsage` is `#[non_exhaustive]`: build via `Default`, assign
        // the `pub` fields.
        let mut u = TokenUsage::default();
        u.input_tokens = input_tokens;

    /// The model this agent calls each turn.
    pub model: Arc<dyn Model>,
    /// Tools available to this agent.
    pub tools: Vec<Arc<dyn Tool<Ctx>>>,
    /// Snapshot of tool/model/output configuration the durable driver plans
    /// against.
    ///
    /// Written by [`crate::worker::TemporalAgentWorkerBuilder::register`] and
    /// read by [`crate::worker::TemporalAgentWorkerBuilder::build`], which
    /// clones it (`def.plan.clone()`) into the `Ctx`-free `AgentPlan` map the
    /// durable workflow plans against via `DurableDriver::new`.
    pub plan: AgentPlan,
}

/// Invoke `model`, draining its event stream into one aggregated
/// [`ModelTurnResult`].
///
/// SDK-free: unit-testable without a Temporal worker. A
/// [`paigasus_helikon_core::ModelError`] from either [`Model::invoke`]
/// itself or a stream-level event degrades to [`ErrorKindPayload::Model`]; a
/// successfully-drained stream that fails to reassemble (invalid
/// tool-call-argument JSON, or parallel tool calls under a blank `call_id`)
/// degrades to [`ErrorKindPayload::Other`].
pub(crate) async fn call_model_inner(
    model: &dyn Model,
    agent_name: &str,
    request: ModelRequest,
    cancel: CancellationToken,
) -> Result<ModelTurnResult, ErrorKindPayload> {
    use futures_util::StreamExt;

    let mut stream = model
        .invoke(request, cancel)
        .await
        .map_err(|e| ErrorKindPayload::Model {
            message: e.to_string(),
        })?;

    let mut acc = ModelTurnAccumulator::new(agent_name);
    while let Some(event) = stream.next().await {
        match event {
            Ok(ev) => acc.observe(&ev),
            Err(e) => {
                return Err(ErrorKindPayload::Model {
                    message: e.to_string(),
                });
            }
        }
    }

    acc.finish()
        .map(ModelTurnResult)
        .map_err(|message| ErrorKindPayload::Other { message })
}

/// Execute one tool call through the shared authorize -> invoke -> redact
/// pipeline ([`execute_tool_call`]) and return its outcome.
///
/// SDK-free. An unknown tool name or a denied/failed call is folded into
/// `outcome.result`'s `Err` string per [`execute_tool_call`]'s contract —
/// this function never panics and never returns an `Err` of its own. The
/// `AgentEvent::PermissionDenied` event `execute_tool_call` may also produce
/// is intentionally dropped here: v0's durable event log
/// (`DurableRunOutcome::events`) does not carry per-tool permission events;
/// the denial reason is already folded into the outcome's `Err` string.
pub(crate) async fn invoke_tool_inner<Ctx: Send + Sync + 'static>(
    def: &DurableAgentDef<Ctx>,
    run_ctx: &RunContext<Ctx>,
    call: ToolCallRequest,
) -> ToolCallOutcome {
    let tool_ctx = run_ctx.to_tool_context();
    execute_tool_call(&def.tools, run_ctx, &tool_ctx, &call)
        .await
        .0
}

/// Render this agent's system-prompt text for `run_ctx`.
///
/// SDK-free.
pub(crate) async fn render_instructions_inner<Ctx: Send + Sync + 'static>(
    def: &DurableAgentDef<Ctx>,
    run_ctx: &RunContext<Ctx>,
) -> String {
    def.instructions.render(run_ctx)
}

// ---------------------------------------------------------------------------
// Temporal activity layer (Step 4): thin, Ctx-erased wrapper over the inner
// functions above.
// ---------------------------------------------------------------------------

//! tool call, not once per run) — keep it small (ids, claims), not bulk data.
//!
//! Payload codecs (custom serialization), claim-check blob offloading, and conversation
//! compaction are named follow-up work, not silent gaps.
//!
//! # Upgrade Discipline and Determinism
//!
//! The workflow's deterministic core is [`paigasus_helikon_core::loop_state::transition`], which
//! lives in a separately versioned crate. Replaying an in-flight workflow against a worker with a
//! **different version of `paigasus-helikon-core` or `paigasus-helikon-runtime-temporal`** can
//! cause non-determinism errors (the workflow's replayed decisions don't match the new code's
//! logic).
//!
//! **Activity input encoding is not a replay hazard.** Temporal's replay check compares an
//! activity's **id** and **type** only — never its input payloads
//! (`temporalio-sdk-core-0.9.0`, `activity_state_machine.rs`, the
//! `IdAndTypeDeterminismChecks` gate). Changing how an activity's arguments are encoded
//! therefore cannot trip the non-determinism checker; *renaming* an activity would. This
//! statement is pinned to `temporalio-* = 1.0.0` / `temporalio-sdk-core = 0.9.0` and must
//! be re-verified on any SDK bump.
//! (Re-verified for 1.0 in SMA-622: `on_activity_task_scheduled` in
//! `temporalio-sdk-core-0.9.0` is byte-identical to the 0.7.0 body and still compares only
//! `act_id`/`activity_id` and `act_type`/`activity_type`, never payloads. Activity and
//! workflow *type names* are derived unchanged as well
//! (`temporalio-macros-1.0.0/src/activities_definitions.rs:548`,
//! `workflow_definitions.rs:644-647`), so registered names are stable across the bump —
//! which is what makes this guarantee useful rather than merely true.
//! Previously re-verified for 0.7 in SMA-549.)
//!
//! **A mixed 0.7/1.0 worker fleet is not proven safe.** The two properties above are
//! established: input encoding is not a replay hazard, and activity/workflow type names
//! do not move. Beyond them, nothing in CI exercises a 1.0 worker replaying a history
//! written by a 0.7 worker — `temporal-it` starts a fresh server, so it only ever replays
//! its own 1.0 histories. Prefer draining in-flight runs across this upgrade, or use a
//! blue-green task queue, exactly as for the 0.5.0 envelope change below.
//!
//! **SMA-484 wire change (activity inputs are envelope-only as of 0.3.0).** Each of
//! `render_instructions` / `call_model` / `invoke_tool` takes one self-describing JSON-object
//! payload, and that is now the **only** shape a worker decodes. The pre-envelope positional
//! shapes (0.2.1 and earlier) are recognized solely to produce a named decode error; SMA-462's
//! 0.2.2 release, which decoded both, is the migration bridge **for 0.2.0 and 0.2.1**. 0.1.x
//! remains outside the support window and fails closed as before — see the 0.1.x note below,
//! because the bridge does not rescue it.
//!
//! **Upgrading from 0.2.0 or 0.2.1 requires a stop at 0.2.2**, for activity inputs:
//!
//! | from → to | outcome |
//! |---|---|
//! | `0.2.2` → `0.3.0` | compatible **both** ways — both encode and decode the envelope; no drain needed for this change |
//! | `0.2.0` / `0.2.1` → `0.3.0`, directly | **broken both ways** — `0.3.0` cannot read legacy-queued tasks, and a `0.2.0`/`0.2.1` worker cannot read an envelope |
//! | `0.2.0` / `0.2.1` → `0.2.2` → `0.3.0` | works, **provided in-flight runs are drained while the fleet is on 0.2.2** |
//!
//! **0.1.x cannot use the bridge.** 0.2.2 decodes the 0.2.0/0.2.1 arities specifically, and only
//! `call_model`'s shape (2 payloads) happens to be unchanged since 0.1.x. A 0.1.x
//! `render_instructions` task is one payload and fails in 0.2.2's envelope arm; a 0.1.x
//! `invoke_tool` task is two payloads, which is not `invoke_tool`'s legacy arity, so it fails
//! there too. A fleet on 0.1.x must therefore drain (or terminate) its in-flight runs outright
//! rather than hopping through 0.2.2. Note the *diagnostic* wording stays "0.2.1 and earlier"
//! deliberately: it describes the shape that arrived, and `call_model`'s 2-payload shape really
//! does date back to 0.1.x.
//!
//! Throughout this section, *drain* means: stop starting new executions on the task queue, and
//! wait until every execution already on it reaches a **terminal** state — not merely pausing
//! new runs.
//!
//! **If a 0.3.0 worker meets a pre-envelope task anyway**, it logs at `ERROR` and fails the
//! attempt **retryably**, so Temporal re-dispatches. That is the recovery path: any worker on
//! 0.2.2 still polling the queue decodes and executes the task, for as long as 0.2.2 can still
//! decode the nested core types in play (see the field-evolution scope below). Re-join one, let
//! in-flight runs drain, then remove it. 0.2.2 and 0.3.0 share identical workflow logic, so a
//! temporary mixed fleet across this pair is not a replay hazard; the one-version-at-a-time rule
//! above still governs every other pair. A run that cannot be drained in an acceptable window is
//! handled with a blue-green task queue (below) or by terminating the execution.
//!
//! **The envelope is unreadable below 0.2.2, and that matters during a rolling deploy.** A
//! **0.2.1-and-earlier** worker handed an envelope payload cannot decode it. It fails the
//! attempt retryably and Temporal re-dispatches until a worker that understands the envelope
//! takes it. The same is true of a 0.3.0 worker handed a pre-envelope payload. Four things bound
//! that recovery:
//!
//! 1. A finite `maximum_attempts` on `model_retry_policy` / `tool_retry_policy` can be exhausted.
//! 2. `WorkflowInput::timeout_ms` interrupts the whole run on its own schedule, regardless of
//!    retry policy.
//! 3. A terminal `render_instructions` failure ends the run; it is not a degraded step.
//! 4. Exhausted `invoke_tool` retries are folded into a tool-error result and fed to the model
//!    rather than failing loudly.
//!
//! **Neither of the first two is on by default.** `render_instructions` is built with no retry
//! policy at all, so the Temporal server default — unlimited attempts — applies; and
//! `WorkflowInput::timeout_ms` is `None` unless set, meaning no deadline. On a default
//! configuration the retry loop is therefore **unbounded**: the run retries indefinitely, writing
//! one `ActivityTaskFailed` event per attempt and consuming workflow history. Do not rely on the
//! failure self-terminating; recovery is operator action.
//!
//! So: **keep the mixed-fleet window short**, and either drain in-flight runs first or ensure
//! retry caps are unlimited and run deadlines generous for the duration of the rollout.
//!
//! **Rolling back.** Once a worker has queued an envelope-shaped activity task, that payload is
//! frozen in the `ActivityTaskScheduled` event and every retry re-delivers it. A rollback to
//! **below 0.2.2** leaves those activities undecodable until the run deadline — which, on a
//! default configuration, does not exist. **Drain in-flight runs before rolling back below 0.2.2.**
//! Rolling back from 0.3.0 to 0.2.2 is safe: 0.2.2 decodes the envelope.
//!
//! **What this buys.** Future additive changes to an activity's input are compatible in both
//! directions, because the envelope is self-describing: unknown fields are ignored and absent
//! fields default. That guarantee is scoped to **the envelope's own field set**. It does *not*
//! extend to the `paigasus-helikon-core` types nested inside those envelopes (`ModelRequest`,
//! `ToolCallRequest`), nor to activity **outputs** — a serde change in any of those breaks the
//! wire exactly as before.
//!
//! **Operational guidance:**
//!
//! 1. **Upgrade one release at a time.** Skipping a release skips the overlap window in which
//!    both shapes are readable (a fleet on 0.2.0 or 0.2.1 goes → 0.2.2 → 0.3.0, draining while
//!    on 0.2.2; 0.1.x has no such overlap and must drain outright).
//! 2. **Drain in-flight runs before redeploying** when in doubt. Agent runs are typically
//!    minutes-to-hours, not months. Alternatively use blue-green task queues: point the old
//!    worker to `"queue-v1"` and the runner to `"queue-v2"`, run new workflows on v2 while old
//!    ones drain from v1, then decommission v1.
//! 3. **Check the CHANGELOG.** Any release whose transition behavior changed is flagged as
//!    replay-breaking.
//! 4. **Production path:** [Temporal Worker Versioning (Build IDs)](https://docs.temporal.io/workers#worker-versioning)
//!    is the long-term solution for zero-downtime updates; support is pending in the Rust SDK.
//!
//! # Links
//!
//! - [API reference (docs.rs)](https://docs.rs/paigasus-helikon-runtime-temporal)
//! - [Guide & concepts](https://smk1085.github.io/paigasus-helikon/) — see [Runtimes](https://smk1085.github.io/paigasus-helikon/concepts/runtimes.html)
//! - [Temporal documentation](https://docs.temporal.io)
//! - [Source & issues](https://github.com/SMK1085/paigasus-helikon)

